<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { isAnswered, isWriting, moveInOrder, submissionIdentity, visibleScore, type Answer, type ExamItem, type SubmissionIdentity } from '../assessment'
const props=defineProps<{request:(path:string,method?:string,body?:unknown)=>Promise<any>;userId:string}>()
const emit=defineEmits<{close:[]}>()
interface Exam {id:string;title:string;max_score:number;instructions:string|string[];items:ExamItem[]}
interface Attempt {id:string;status:string;total:number|null;created_at:string;published_at:string|null}
const exam=ref<Exam|null>(null),answers=ref<Record<string,Answer>>({}),attempts=ref<Attempt[]>([]),active=ref(0)
const loading=ref(true),busy=ref(false),error=ref(''),notice=ref(''),storageNotice=ref(''),submitted=ref<Attempt|null>(null),confirm=ref(false)
const identity=ref<SubmissionIdentity|null>(null)
const draftKey=computed(()=>`caocuan:exam:${props.userId}:${exam.value?.id??'loading'}`)
const question=computed(()=>exam.value?.items[active.value]),answered=computed(()=>exam.value?.items.filter(q=>isAnswered(q,answers.value[q.id])).length??0)
const complete=computed(()=>!!exam.value&&answered.value===exam.value.items.length)
const instructions=computed(()=>Array.isArray(exam.value?.instructions)?exam.value.instructions.join(' '):exam.value?.instructions??'')
const typeNames:Record<string,string>={single:'单项选择',multi:'多项选择',order:'情节排序',match:'台词用意配对',scenario:'情境判断',fill:'填空',short:'简答',essay:'论述',reflection:'个人感悟'}
function persist(){if(!exam.value||submitted.value)return;try{localStorage.setItem(draftKey.value,JSON.stringify({answers:answers.value,active:active.value,identity:identity.value}))}catch{storageNotice.value='此浏览器未能保存草稿，请在本页完成后交卷。'}}
watch(answers,persist,{deep:true});watch(active,persist)
function setAnswer(id:string,value:Answer){if(busy.value||submitted.value)return;answers.value={...answers.value,[id]:value};confirm.value=false;notice.value='';error.value=''}
function goToQuestion(index:number){if(busy.value||submitted.value||!exam.value)return;active.value=Math.min(Math.max(index,0),exam.value.items.length-1)}
function closePanel(){if(!busy.value)emit('close')}
function setConfirmation(value:boolean){if(!busy.value)confirm.value=value}
function toggle(id:string,option:string){const values=Array.isArray(answers.value[id])?[...answers.value[id] as string[]]:[];setAnswer(id,values.includes(option)?values.filter(v=>v!==option):[...values,option])}
function order(q:ExamItem):string[]{return Array.isArray(answers.value[q.id])?answers.value[q.id] as string[]:(q.options??[]).map(o=>o.id)}
function matchValue(id:string,key:string):string{const value=answers.value[id];return value&&typeof value==='object'&&!Array.isArray(value)?value[key]??'':''}
function setMatch(q:string,left:string,value:string){const old=answers.value[q];setAnswer(q,{...(old&&typeof old==='object'&&!Array.isArray(old)?old:{}),[left]:value})}
function label(q:ExamItem,id:string){return q.options?.find(o=>o.id===id)?.text??id}
function date(value:string){return new Date(value).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})}
async function refreshAttempts(){try{attempts.value=(await props.request('/api/exam/attempts')).attempts;if(submitted.value)submitted.value=attempts.value.find(a=>a.id===submitted.value!.id)??submitted.value}catch(e){error.value=e instanceof Error?e.message:'成绩未能更新，请重试。'}}
async function load(){loading.value=true;error.value='';try{
  const [paper,list]=await Promise.all([props.request('/api/exam'),props.request('/api/exam/attempts')]);exam.value=paper;attempts.value=list.attempts
  try{const raw=localStorage.getItem(draftKey.value);if(raw){const d=JSON.parse(raw);if(d.answers&&typeof d.answers==='object'&&!Array.isArray(d.answers)){answers.value=Object.fromEntries(Object.entries(d.answers).filter(([id])=>paper.items.some((q:ExamItem)=>q.id===id))) as Record<string,Answer>;active.value=Math.min(Math.max(Number(d.active)||0,0),paper.items.length-1);identity.value=d.identity??null;notice.value='已接续本机草稿。'}}}catch{storageNotice.value='旧草稿无法读取，本次请重新作答。'}
}catch(e){error.value=e instanceof Error?e.message:'试卷未能打开，请重试。'}finally{loading.value=false}}
async function submit(){if(busy.value||submitted.value||!complete.value)return;const submissionAnswers=JSON.parse(JSON.stringify(answers.value)) as Record<string,Answer>;busy.value=true;error.value='';identity.value=submissionIdentity(submissionAnswers,identity.value,()=>crypto.randomUUID());persist()
try{submitted.value=await props.request('/api/exam/attempts','POST',{exam_id:exam.value?.id,answers:submissionAnswers,request_id:identity.value.requestId});confirm.value=false;try{localStorage.removeItem(draftKey.value)}catch{};await refreshAttempts()}
catch(e){error.value=e instanceof Error?e.message:'交卷未完成。你的答案仍在，重试不会重复交卷。'}finally{busy.value=false}}
onMounted(load)
</script>

<template>
<section class="exam-shell" aria-label="草船借箭课题测试" :aria-busy="busy">
  <header class="exam-header"><div><span class="exam-kicker">江上归来 · 课题测试</span><h1>{{exam?.title??'草船借箭'}}</h1></div><button class="exam-return" :disabled="busy" @click="closePanel">返回课件 <span aria-hidden="true">↗</span></button></header>
  <p v-if="error" class="exam-error" role="alert">{{error}} <button v-if="!exam" @click="load">重新打开</button></p>
  <div v-if="loading" class="exam-empty" role="status">正在展开考卷…</div>
  <div v-else-if="submitted" class="exam-result">
    <span class="exam-kicker">本次答卷已收存</span><h2>已交卷</h2>
    <div class="result-score"><strong>{{visibleScore(submitted)}}</strong><span v-if="submitted.status==='published'&&submitted.total!==null">/ 100</span></div>
    <p>{{submitted.status==='published'?'本次课题测试成绩已发布。':'表达题批阅完成后，由教师发布本次总分。'}}</p>
    <div class="exam-result-actions"><button class="exam-gold" :disabled="busy" @click="refreshAttempts">查看成绩状态</button><button class="exam-return" :disabled="busy" @click="closePanel">回到江上</button></div>
  </div>
  <div v-else-if="exam&&question" class="exam-layout">
    <aside class="exam-navigation"><div class="exam-total"><strong>100</strong><span>分 · 全卷</span></div><p>已答 {{answered}} / {{exam.items.length}}</p>
      <nav aria-label="题目导航"><button v-for="(q,i) in exam.items" :key="q.id" :disabled="busy" :class="{current:i===active,done:isAnswered(q,answers[q.id])}" :aria-label="`第${i+1}题，${isAnswered(q,answers[q.id])?'已作答':'未作答'}`" :aria-current="i===active?'step':undefined" @click="goToQuestion(i)">{{String(i+1).padStart(2,'0')}}<span aria-hidden="true">{{isAnswered(q,answers[q.id])?'·':''}}</span></button></nav>
      <small>草稿只保存在此浏览器。<br>提交后等待教师发布成绩。</small>
      <details v-if="attempts.length" class="exam-history"><summary>往次成绩</summary><div v-for="a in attempts" :key="a.id"><time>{{date(a.created_at)}}</time><strong>{{visibleScore(a)}}</strong></div></details>
    </aside>
    <main class="exam-paper"><p class="exam-instructions">{{instructions}}</p><div class="exam-question-meta"><span>第 {{active+1}} 题 · {{typeNames[question.type]}}</span><span>{{question.points}} 分</span></div><h2>{{question.prompt}}</h2>
      <blockquote v-if="question.material" class="exam-material">{{question.material}}</blockquote>
      <figure v-if="question.id==='q10'&&question.type==='short'" class="exam-scene"><svg viewBox="0 0 720 230" role="img" aria-labelledby="common-scene-title common-scene-desc"><title id="common-scene-title">岸上停射，哨艇正在靠近</title><desc id="common-scene-desc">共同场景示意：上方曹营已经停止放箭，小哨艇从寨门向江上的船队靠近。鲁肃向诸葛亮发问，韩伯在船舵旁等候安排。</desc><rect width="720" height="230" fill="#223b43"/><path d="M0 57H720M0 103H720M0 156H720M0 204H720" stroke="#44616a" stroke-width="1"/><path d="M0 0H720V46L520 55 350 43 170 54 0 40Z" fill="#596458"/><path d="M300 17V48M328 17V48M356 17V48M384 17V48M412 17V48" stroke="#b5ae91" stroke-width="6"/><path d="M345 80L405 80 393 96 358 96Z" fill="#bba77a"/><path d="M376 106V132M370 126L376 134 382 126" fill="none" stroke="#d2b776" stroke-width="3"/><path d="M205 177H499L472 207H235Z" fill="#a99870"/><path d="M250 175V151M265 175V147M280 175V151M425 175V151M440 175V147M455 175V151" stroke="#8d9e75" stroke-width="9"/><circle cx="320" cy="158" r="8" fill="#d2c7a6"/><path d="M320 166V184" stroke="#d2c7a6" stroke-width="10"/><circle cx="370" cy="158" r="8" fill="#d2c7a6"/><path d="M370 166V184" stroke="#d2c7a6" stroke-width="10"/><path d="M477 183L507 155" stroke="#c7b98e" stroke-width="4"/><text x="455" y="31" fill="#f0e6cc" font-size="16">曹营：已停射</text><text x="421" y="92" fill="#f0e6cc" font-size="16">哨艇正在靠近</text><text x="50" y="185" fill="#f0e6cc" font-size="16">鲁肃、诸葛亮</text><text x="516" y="166" fill="#f0e6cc" font-size="16">韩伯待命</text></svg><figcaption>本题共同场景示意，所有路线使用相同材料。</figcaption></figure>
      <div v-if="question.type==='scenario'&&question.parts" class="exam-case"><fieldset v-for="part in question.parts" :key="part.id" :disabled="busy"><legend>{{part.prompt}} <small>{{part.points}} 分</small></legend><input v-if="part.type==='number'" type="text" :disabled="busy" inputmode="numeric" maxlength="9" :aria-label="part.prompt" :value="matchValue(question.id,part.id)" @input="setMatch(question.id,part.id,($event.target as HTMLInputElement).value)"><label v-for="option in part.options" :key="option.id"><input type="radio" :disabled="busy" :name="`${question.id}-${part.id}`" :checked="matchValue(question.id,part.id)===option.id" @change="setMatch(question.id,part.id,option.id)">{{option.text}}</label></fieldset></div>
      <fieldset v-else-if="['single','scenario','multi'].includes(question.type)" class="exam-options" :disabled="busy"><legend class="sr-only">请选择答案</legend>
        <label v-for="(o,i) in question.options" :key="o.id" :class="{selected:question.type==='multi'?Array.isArray(answers[question.id])&&(answers[question.id] as string[]).includes(o.id):answers[question.id]===o.id}">
          <input v-if="question.type==='multi'" type="checkbox" :disabled="busy" :checked="Array.isArray(answers[question.id])&&(answers[question.id] as string[]).includes(o.id)" @change="toggle(question.id,o.id)">
          <input v-else type="radio" :disabled="busy" :name="question.id" :value="o.id" :checked="answers[question.id]===o.id" @change="setAnswer(question.id,o.id)"><span class="option-letter">{{String.fromCharCode(65+i)}}</span><span>{{o.text}}</span>
        </label>
      </fieldset>
      <div v-else-if="question.type==='order'" class="exam-order"><p class="exam-hint">按故事发生的先后调整。也可保持原顺序，点击确认。</p><ol><li v-for="(id,i) in order(question)" :key="id"><span class="order-index">{{i+1}}</span><span>{{label(question,id)}}</span><div><button :disabled="busy||i===0" :aria-label="`上移${label(question,id)}`" @click="setAnswer(question.id,moveInOrder(order(question),i,-1))">↑</button><button :disabled="busy||i===order(question).length-1" :aria-label="`下移${label(question,id)}`" @click="setAnswer(question.id,moveInOrder(order(question),i,1))">↓</button></div></li></ol><button class="exam-return" :disabled="busy" @click="setAnswer(question.id,[...order(question)])">确认当前顺序{{isAnswered(question,answers[question.id])?' ✓':''}}</button></div>
      <div v-else-if="question.type==='match'" class="exam-match"><label v-for="left in question.left" :key="left.id"><span>{{left.text}}</span><select :disabled="busy" :value="matchValue(question.id,left.id)" @change="setMatch(question.id,left.id,($event.target as HTMLSelectElement).value)"><option value="" disabled>选择对应项</option><option v-for="right in question.right" :key="right.id" :value="right.id">{{right.text}}</option></select></label></div>
      <div v-else-if="question.type==='fill'" class="exam-fill"><label :for="question.id">填写空缺内容</label><input :id="question.id" :disabled="busy" :value="typeof answers[question.id]==='string'?answers[question.id]:''" type="text" maxlength="200" autocomplete="off" placeholder="在这里填写" @input="setAnswer(question.id,($event.target as HTMLInputElement).value)"><small>按题意作答；题目允许的同义表述会一并核对。</small></div>
      <div v-else-if="isWriting(question)" class="exam-writing"><label class="sr-only" :for="question.id">你的回答</label><textarea :disabled="busy" :id="question.id" :value="typeof answers[question.id]==='string'?answers[question.id] as string:''" maxlength="2000" rows="7" :placeholder="question.type==='reflection'?'回想一次具体选择，写下当时的想法和现在的认识。':question.type==='essay'?'先提出看法，再结合给定情境展开说明。':'对照题目要求，用自己的话回答。'" @input="setAnswer(question.id,($event.target as HTMLTextAreaElement).value)"></textarea><div><small>{{question.suggested_length?question.suggested_length+'；':question.suggested_words?`建议${question.suggested_words}；`: ""}}用自己的话完成，字数不作机械扣分。</small><span>{{String(answers[question.id]??'').length}} / 2000</span></div></div>
      <p v-if="notice||storageNotice" class="exam-save-note" role="status">{{storageNotice||notice}}</p>
      <footer class="exam-controls"><button class="exam-return" :disabled="busy||active===0" @click="goToQuestion(active-1)">← 上一题</button><button v-if="active<exam.items.length-1" class="exam-gold" :disabled="busy" @click="goToQuestion(active+1)">下一题 →</button><button v-else class="exam-gold" :disabled="!complete||busy" @click="setConfirmation(true)">检查并交卷</button></footer>
      <div v-if="confirm" class="exam-confirm" role="region" aria-label="交卷确认"><p>全卷 {{exam.items.length}} 题已作答。交卷后，本次答卷将不再修改。</p><button class="exam-gold" :disabled="busy" @click="submit">{{busy?'正在交卷…':'确认交卷'}}</button><button class="exam-return" :disabled="busy" @click="setConfirmation(false)">继续检查</button></div>
      <p v-else-if="active===exam.items.length-1&&!complete" class="exam-hint">还有 {{exam.items.length-answered}} 题未完成，可从左侧题号返回。</p>
    </main>
  </div>
</section>
</template>

<style scoped>
.exam-fill{display:grid;gap:14px;padding:24px 0}.exam-fill label{font-size:14px;color:#617161}.exam-fill input{width:min(100%,560px);padding:16px 6px;background:transparent;border:0;border-bottom:2px solid #8d9c7b;font:22px/1.6 Georgia,'Microsoft YaHei',serif;color:#283f37}.exam-fill small{font-size:12px;color:#788370}.exam-material{white-space:pre-wrap;line-height:1.9;border-left:2px solid #a9af8e;padding:14px 22px;margin:18px 0;background:#e9eddf}.exam-writing textarea{min-height:220px}

.exam-shell{position:fixed;inset:0;z-index:60;overflow:auto;background:radial-gradient(ellipse at 78% 0,#294047 0,transparent 55%),#101d22;color:#e6e3d5;font-family:'Microsoft YaHei',sans-serif;padding:clamp(20px,4vw,64px);box-sizing:border-box}.exam-shell *{box-sizing:border-box}.exam-header{display:flex;justify-content:space-between;align-items:center;gap:24px;border-bottom:1px solid #8f92774d;padding-bottom:24px}.exam-kicker{font-size:12px;color:#c0af7c;letter-spacing:.25em}.exam-header h1{font-family:'STKaiti','KaiTi',serif;font-size:32px;font-weight:400;margin:12px 0 0;letter-spacing:.15em}.exam-return,.exam-gold{font:inherit;border:1px solid #ad9b6666;background:transparent;color:#e0d9bd;padding:12px 20px;cursor:pointer;min-height:44px}.exam-return:disabled,.exam-gold:disabled{opacity:.4;cursor:default}.exam-gold{background:#bba56a;color:#152328;border-color:#bba56a}.exam-layout{display:grid;grid-template-columns:160px minmax(0,820px);gap:clamp(28px,5vw,80px);justify-content:center;padding-top:36px}.exam-total{display:flex;align-items:baseline;gap:8px}.exam-total strong{font-size:48px;font-family:Georgia,serif;font-weight:400;color:#cfbb83}.exam-total span,.exam-navigation p,.exam-navigation small{color:#9faeaa;font-size:12px;line-height:1.8}.exam-navigation nav{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:22px 0}.exam-navigation nav button{position:relative;min-height:42px;background:transparent;color:#8d9e9e;border:1px solid #7387844d;cursor:pointer;font:inherit}.exam-navigation nav button.done{color:#d8d3bd;border-color:#bba56a80}.exam-navigation nav button.current{background:#bba56a;color:#152328}.exam-navigation nav button span{position:absolute;right:5px;bottom:0}.exam-instructions{color:#aebcba;font-size:13px;line-height:1.8;margin:0 0 28px}.exam-question-meta{display:flex;justify-content:space-between;color:#c2ae78;font-size:12px;letter-spacing:.12em}.exam-paper h2{font-family:'STSong','SimSun',serif;font-size:clamp(21px,2vw,28px);line-height:1.65;font-weight:400;margin:18px 0 26px;white-space:pre-wrap}.exam-options{border:0;padding:0;margin:0;display:grid;gap:12px}.exam-options label{display:flex;gap:16px;align-items:center;min-height:64px;padding:16px 22px;border:1px solid #84928c55;cursor:pointer;font-size:15px;line-height:1.6;transition:background .18s}.exam-options label.selected{border-color:#c4ae72;background:#8b80552a}.exam-options label:hover{background:#ffffff08}.option-letter{font-family:Georgia,serif;color:#c1ae79}.exam-options input{accent-color:#c4ae72}.exam-hint,.exam-save-note{color:#aebcba;font-size:13px;line-height:1.6}.exam-controls{display:flex;justify-content:space-between;gap:16px;margin-top:32px;padding-top:22px;border-top:1px solid #85958c44}.exam-scene{margin:0 0 24px}.exam-scene svg{width:100%;height:auto;border:1px solid #84928c55}.exam-scene figcaption{font-size:12px;color:#aebcba;margin-top:8px}.exam-case fieldset{border:1px solid #84928c55;margin:20px 0;padding:20px}.exam-case legend{font-size:16px;line-height:1.8}.exam-case legend small{color:#c2ae78}.exam-case label{display:flex;gap:12px;padding:12px 0;line-height:1.7}.exam-case input[type=text]{background:#213238;color:#e5e2d4;border:1px solid #9eab8a66;padding:14px;font:inherit;width:100%;max-width:280px}.exam-order ol{list-style:none;padding:0;display:grid;gap:10px}.exam-order li{display:flex;align-items:center;gap:16px;padding:14px 16px;border-bottom:1px solid #82918c55}.exam-order li>span:nth-child(2){flex:1;font-size:15px;line-height:1.6}.order-index{color:#bca974;font-family:Georgia,serif}.exam-order li button{background:#ffffff0a;color:#e6dfc7;border:1px solid #8a967655;font:inherit;width:38px;height:38px;margin-left:6px;cursor:pointer}.exam-order li button:disabled{opacity:.25}.exam-match{display:grid;gap:18px}.exam-match label{display:grid;grid-template-columns:1fr 1fr;align-items:center;gap:20px;font-size:15px;line-height:1.6}.exam-match select{background:#213238;color:#e5e2d4;border:1px solid #9eab8a66;padding:14px;font:inherit;min-width:0}.exam-writing textarea{width:100%;background:#d9d5bd0a;color:#eae4ce;border:1px solid #9a9d7e77;padding:20px;font:16px/1.9 'Microsoft YaHei',sans-serif;resize:vertical;min-height:190px}.exam-writing>div{display:flex;justify-content:space-between;gap:20px;margin-top:10px;color:#a9b5ad;font-size:12px;line-height:1.6}.exam-writing small{max-width:80%}.exam-confirm{border-top:1px solid #bca974;padding-top:18px;margin-top:20px;font-size:14px;line-height:1.8}.exam-confirm button{margin-right:12px}.exam-error{color:#f2b4a5;border-left:2px solid #db9d87;padding:12px 18px;font-size:14px}.exam-error button{background:none;border:0;color:inherit;text-decoration:underline;cursor:pointer}.exam-empty{margin:100px auto;text-align:center;color:#b6c0b9}.exam-result{max-width:740px;margin:9vh auto}.exam-result h2{font-family:'STKaiti','KaiTi',serif;font-weight:400;font-size:clamp(36px,5vw,68px);line-height:1.5;letter-spacing:.08em}.result-score{color:#c7b078;display:flex;gap:16px;align-items:baseline}.result-score strong{font:48px Georgia,'SimSun',serif}.result-score span{font-size:20px}.exam-result p{color:#acbbb7;line-height:1.8}.exam-result-actions{display:flex;gap:16px;margin-top:32px}.exam-history{margin-top:24px;font-size:12px;color:#b5bca9}.exam-history summary{cursor:pointer;padding:10px 0}.exam-history>div{display:flex;flex-direction:column;gap:6px;border-bottom:1px solid #82918c44;padding:12px 0}.exam-history strong{color:#d0bc85;font-weight:400}.sr-only{position:absolute;width:1px;height:1px;padding:0;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}button:focus-visible,select:focus-visible,textarea:focus-visible,input:focus-visible{outline:2px solid #e6ce88;outline-offset:4px}@media(max-width:700px){.exam-shell{padding:18px}.exam-header{gap:12px}.exam-header h1{font-size:25px}.exam-header .exam-return{font-size:12px;padding:9px}.exam-layout{display:block;padding-top:20px}.exam-navigation{display:grid;grid-template-columns:auto 1fr;gap:0 20px;align-items:center}.exam-total strong{font-size:30px}.exam-navigation nav{grid-column:1/-1;display:flex;overflow:auto;margin:12px 0 24px}.exam-navigation nav button{flex:0 0 40px}.exam-navigation small,.exam-history{display:none}.exam-match label{grid-template-columns:1fr}.exam-paper h2{font-size:22px}.exam-options label{padding:12px;gap:10px}.exam-result{margin-top:50px}}
</style>

